package views

import "fmt"

// isAutoGeneratedAlias reports whether name is a default derived from the
// model or API type rather than an alias the user chose. Older releases stored
// defaults as "model (api_type)"; InitDB migrates persisted rows, but probe
// input and in-memory values can still carry the legacy shape.
//
// An empty name is not considered auto-generated here: callers decide whether
// to fill it (the tester does, the probe leaves a deliberately cleared alias
// alone).
func isAutoGeneratedAlias(name, model, apiType string) bool {
	if name == "" || model == "" {
		return false
	}
	return name == model || name == fmt.Sprintf("%s (%s)", model, apiType)
}
